+// A green-context stream carved to `sm_count` SMs (<= sm_count(device_id)). Created once per
+// device and cached for the process lifetime, since green contexts are expensive to set up
+// and the margin isn't expected to change after the first call. `stream == nullptr` means no
+// carveout is in effect (margin zero, or the platform/driver couldn't create one), in which
+// case `sm_count` is the full device SM count.
+struct Carveout {
+  cudaStream_t stream = nullptr;
+  int sm_count = 0;
+};
