+  std::lock_guard<std::mutex> lock(mutex);
+  auto it = cache.find(device_id);
+  if (it != cache.end()) return it->second;
+
+  const int device_sm_count = sm_count(device_id);
+  const int margin = grouped_quantize_sm_margin();
+  NVTE_CHECK(margin >= 0 && margin < device_sm_count, "NVTE_GROUPED_QUANTIZE_SM_MARGIN (", margin,
+             ") must be between 0 (inclusive) and the device SM count (", device_sm_count,
+             ") (exclusive).");
+
+  Carveout carveout{nullptr, device_sm_count};
+#if CUDART_VERSION >= 12040
+  try {
+    CUdevice cu_device;
+    NVTE_CALL_CHECK_CUDA_DRIVER(cuDeviceGet, &cu_device, device_id);
+
+    // Green-context symbols postdate cuda_driver::call()'s default resolution version (12.1)
+    // and their ABI has changed since, so resolve against the exact CUDA version this
+    // library was built with.
+    CUdevResource sm_resource;
+    NVTE_CALL_CHECK_CUDA_DRIVER_VERSIONED(cuDeviceGetDevResource, CUDART_VERSION, cu_device,
+                                          &sm_resource, CU_DEV_RESOURCE_TYPE_SM);
+
+    CUdevResource carved_resource;
+    unsigned int num_groups = 1;
+    NVTE_CALL_CHECK_CUDA_DRIVER_VERSIONED(cuDevSmResourceSplitByCount, CUDART_VERSION,
+                                          &carved_resource, &num_groups, &sm_resource, nullptr, 0u,
+                                          static_cast<unsigned int>(device_sm_count - margin));
+    NVTE_CHECK(num_groups > 0, "Failed to partition ", device_sm_count - margin,
+               " SMs for NVTE_GROUPED_QUANTIZE_SM_MARGIN.");
